# BenchGo V3 — École Primaire, Classe 3 (CE2)

Toutes les fonctions JavaScript sont complètes et exécutables.

---

### tache_3a

```javascript
function dernierElement(tableau) {
    if (!tableau || tableau.length === 0) {
        return undefined;
    }
    return tableau[tableau.length - 1];
}
```

---

### tache_3b

```javascript
function compterJusqua(n) {
    if (n < 1) {
        return [];
    }
    return Array.from({ length: n }, (_, i) => i + 1);
}
```

---

### tache_3c

```javascript
function remplacerLettre(mot, ancienne, nouvelle) {
    return mot.split(ancienne).join(nouvelle);
}
```

---

### tache_3d

```javascript
function sommeTableau(tableau) {
    return tableau.reduce((sum, val) => sum + val, 0);
}
```

---

### tache_3e

```javascript
function contientA(mot) {
    return mot.toLowerCase().includes('a');
}
```

---

### algo_facile_1

```javascript
function validerParentheses(s) {
    let count = 0;
    for (let char of s) {
        if (char === '(') count++;
        else if (char === ')') count--;
        if (count < 0) return false;
    }
    return count === 0;
}
```

---

### algo_facile_2

```javascript
function fibonacci(n) {
    if (n === 0) return 0;
    if (n === 1) return 1;
    let a = 0, b = 1;
    for (let i = 2; i <= n; i++) {
        [a, b] = [b, a + b];
    }
    return b;
}
```

---

### algo_moyen_1

```javascript
function motsUniques(s) {
    const words = s.trim().split(/\s+/);
    return new Set(words).size;
}
```

---

### algo_difficile_1

```javascript
function aplanirTableau(tab) {
    return tab.flat();
}
```

---

### algo_defi

```javascript
function rotationDroite(tab, k) {
    if (tab.length === 0) return [];
    k = ((k % tab.length) + tab.length) % tab.length;
    if (k === 0) return [...tab];
    return [...tab.slice(-k), ...tab.slice(0, -k)];
}
```

