function creerFilePriorite() {
  const heap = []; // Each element is { val, priorite }

  function echanger(i, j) {
    const temp = heap[i];
    heap[i] = heap[j];
    heap[j] = temp;
  }

  function remonter(i) {
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (heap[i].priorite < heap[parent].priorite) {
        echanger(i, parent);
        i = parent;
      } else {
        break;
      }
    }
  }

  function descendre(i) {
    const longueur = heap.length;
    while (true) {
      const gauche = 2 * i + 1;
      const droite = 2 * i + 2;
      let plusPetit = i;

      if (gauche < longueur && heap[gauche].priorite < heap[plusPetit].priorite) {
        plusPetit = gauche;
      }
      if (droite < longueur && heap[droite].priorite < heap[plusPetit].priorite) {
        plusPetit = droite;
      }
      if (plusPetit !== i) {
        echanger(i, plusPetit);
        i = plusPetit;
      } else {
        break;
      }
    }
  }

  return {
    enqueue: function(val, priorite) {
      heap.push({ val, priorite });
      remonter(heap.length - 1);
    },
    dequeue: function() {
      if (heap.length === 0) return undefined;
      if (heap.length === 1) return heap.pop().val;

      const min = heap[0].val;
      heap[0] = heap.pop();
      descendre(0);
      return min;
    },
    taille: function() {
      return heap.length;
    }
  };
}
