function creerProxy(cible, gestionnaire) {
  const handlers = {
    get: {},
    set: {}
  };

  if (gestionnaire.get) {
    handlers.get = gestionnaire.get;
  }
  if (gestionnaire.set) {
    handlers.set = gestionnaire.set;
  }

  const proxy = Object.create(Object.prototype);

  Object.defineProperty(proxy, '_cible', {
    value: cible,
    writable: true,
    configurable: true
  });

  const handlerFuncs = {
    get: function(prop) {
      if (handlers.get[prop]) {
        return handlers.get[prop](cible[prop], prop);
      }
      return cible[prop];
    },
    set: function(prop, valeur) {
      if (handlers.set[prop]) {
        const result = handlers.set[prop](cible[prop], prop, valeur);
        if (result !== false) {
          cible[prop] = valeur;
        }
        return true;
      }
      cible[prop] = valeur;
      return true;
    }
  };

  return new Proxy(proxy, {
    get: function(obj, prop) {
      if (prop === '_cible') return cible;
      if (prop in handlerFuncs) {
        return (...args) => handlerFuncs[prop](...args);
      }
      if (handlers.get[prop]) {
        return handlers.get[prop](cible[prop], prop);
      }
      return cible[prop];
    },
    set: function(obj, prop, valeur) {
      if (handlers.set[prop]) {
        const result = handlers.set[prop](cible[prop], prop, valeur);
        if (result !== false) {
          cible[prop] = valeur;
        }
        return true;
      }
      cible[prop] = valeur;
      return true;
    }
  });
}

// Alternative manuelle complète (sans utiliser Proxy):
function creerProxyManuel(cible, gestionnaire) {
  const result = {};

  const getTrap = gestionnaire.get || null;
  const setTrap = gestionnaire.set || null;

  return new Proxy(result, {
    get: function(obj, prop) {
      if (prop === Symbol.iterator) {
        return cible[Symbol.iterator].bind(cible);
      }
      if (getTrap) {
        return getTrap(cible, prop);
      }
      return cible[prop];
    },
    set: function(obj, prop, valeur) {
      if (setTrap) {
        setTrap(cible, prop, valeur);
        cible[prop] = valeur;
      } else {
        cible[prop] = valeur;
      }
      return true;
    }
  });
}
