function creerProxy(cible, gestionnaire) {
  // Objet interne pour stocker les valeurs
  const storage = Object.assign({}, cible);

  // Prototype avec getter/setter pour intercepter TOUTES les propriétés
  const handlerProto = {
    get: function(prop) {
      if (gestionnaire.get) {
        return gestionnaire.get(storage, prop);
      }
      return storage[prop];
    },
    set: function(prop, valeur) {
      if (gestionnaire.set) {
        gestionnaire.set(storage, prop, valeur);
      }
      storage[prop] = valeur;
      return true;
    }
  };

  // Créer le proxy via prototype pour intercepter les nouvelles propriétés
  const proxy = Object.create(handlerProto);

  // Pour les propriétés existantes, définir des accesseurs explicites
  Object.keys(storage).forEach(function(prop) {
    Object.defineProperty(proxy, prop, {
      get: function() {
        return handlerProto.get(prop);
      },
      set: function(valeur) {
        handlerProto.set(prop, valeur);
      },
      enumerable: true,
      configurable: true
    });
  });

  return proxy;
}
