async function executerAvecRetry(operation, maxTentatives = 3) {
    if (typeof operation !== "function") {
        throw new Error("Operation doit être une fonction asynchrone");
    }

    let lastError;

    for (let tentative = 1; tentative <= maxTentatives; tentative++) {
        try {
            return await operation();
        } catch (err) {
            lastError = err;
            const isLastTentative = tentative === maxTentatives;

            if (!isLastTentative) {
                // Exponential backoff: 2^(tentative-1) * 1000ms, max 30s
                const delai = Math.min(Math.pow(2, tentative - 1) * 1000, 30000);
