    while (i < a.length) {
        prev = curr;
        curr = a[i++];
        count++;
        if (count === medianIndex) {
            if (isEven) {
                return (prev + curr) / 2;
            }
            return curr;
        }
    }

    while (j < b.length) {
        prev = curr;
        curr = b[j++];
        count++;
        if (count === medianIndex) {
            if (isEven) {
                return (prev + curr) / 2;
            }
            return curr;
        }
    }

    return (prev + curr) / 2;
}
