function plusLongueSousSuiteCroissante(tab) {
    if (tab.length === 0) return 0;

    const dp = new Array(tab.length).fill(1);
    let maxLength = 1;

    for (let i = 1; i < tab.length; i++) {
        for (let j = 0; j < i; j++) {
            if (tab[j] < tab[i]) {
                dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
        maxLength = Math.max(maxLength, dp[i]);
    }

    return maxLength;
}
