function medianeDeuxTries(a, b) {
    const totalLength = a.length + b.length;
    const isEven = totalLength % 2 === 0;
    const midIndex = Math.floor(totalLength / 2);

    let i = 0, j = 0, current = 0, prev = 0;

    while (i + j <= midIndex) {
        prev = current;

        if (i < a.length && (j >= b.length || a[i] <= b[j])) {
